// Static manifest generated by engine:build; no metadata API at runtime.
import { mkdir, writeFile, readFile, access } from 'node:fs/promises';
const catalog = JSON.parse(await readFile('shared/catalog.json','utf8'));
let next = 0, saved = 0; const failed=[];
async function worker() {
  while(next<catalog.length) {
    const card=catalog[next++]; const [set,number]=card.cardId.split('-');
    const dest=`public/cards/${set}/${number}.png`;
    try { await access(dest); continue; } catch {}
    try {
      const response=await fetch(`https://images.pokemontcg.io/${set}/${number}.png`,{signal:AbortSignal.timeout(20000)});
      if(!response.ok)throw Error(String(response.status));
      await mkdir(`public/cards/${set}`,{recursive:true});
      await writeFile(dest,Buffer.from(await response.arrayBuffer()));saved++;
    } catch(e) { failed.push({id:card.cardId,error:String(e)}); }
  }
}
await Promise.all(Array.from({length:6},worker));
console.log(JSON.stringify({saved,failed},null,2));
if(failed.length)process.exitCode=1;
